(function(){

  var APP_LINK_NAME    = "";                           // EDIT ME (usually leave blank)
  var REPORT_LINK_NAME = "Claim_Payments_Portal";         // report to read from
  var CLAIMS_REPORT_LINK_NAME = "Doctors_Claim_Report";    // report containing service dates

  var FIELD = {
    paymentId  : "Payment_ID",          // EDIT ME — flat field on the parent record
    paymentDate: "payment_date",        // EDIT ME — flat field on the parent record (note: lowercase link name)
    doctor     : "Doctor",              // EDIT ME — lookup field on the parent record
    hospital   : "Hospital",            // EDIT ME — lookup field on the parent record
    payerName  : "Payer_Name",          // EDIT ME — flat field on the parent record
    method     : "Payment_Method",      // EDIT ME — flat field on the parent record
    subform    : "Payment_Items",       // EDIT ME — subform field holding the line items array
    patient    : "Patient",             // EDIT ME — field inside each Payment_Items line item
    itemCode   : "Item",           // EDIT ME — field inside each Payment_Items line item
    allocated  : "Allocated_Amount",    // EDIT ME — field inside each Payment_Items line item
    adjustment : "Adjustment_Amount",   // EDIT ME — field inside each Payment_Items line item
    balance    : "Balance_Due",
    claimId : "Claim_ID"
  };
  var CLAIM_FIELD = {
  claimId: "Claim_ID",        // flat field on the claim record (shows CLM-1282)
  lines: "Claim_Lines",       // subform holding the claim lines
  itemCode: "Item",           // field inside each claim line
  dateOfService: "Date_of_Service"  // field inside each claim line
};

var USER_SCOPE = {
  enabled: true,
  paymentCriteria: '(Doctor.Email == "{{email}}")',
  claimCriteria:   '(Doctor.Email == "{{email}}")',
  adminEmails: []   // e.g. ["admin@medielves.com.au"] to see everything
};
var activePaymentCriteria = "";
var activeClaimCriteria   = "";
var loginUserEmail = "";

  var rawRecords  = [];     // parent records exactly as returned by the API (one per Add_Payment_Report row)
  var rawClaimRecords = [];
  var allRecords  = [];     // flattened: one row per Payment_Items line item, merged with its parent's fields
  var viewRecords = [];     // currently filtered/displayed dataset


  var __uidCounter = 0;
  function flattenRecords(records){
    var out = [];
    records.forEach(function(rec){
      var items = rec[FIELD.subform];
      if(Array.isArray(items) && items.length){
        items.forEach(function(item){
          var merged = {};
          for(var k in rec){ if(k !== FIELD.subform) merged[k] = rec[k]; }
          for(var k2 in item){ merged[k2] = item[k2]; }
          merged.__uid = "row" + (++__uidCounter);
          out.push(merged);
        });
      } else {
        // No line items on this record — still show it so nothing silently disappears.
        rec.__uid = "row" + (++__uidCounter);
        out.push(rec);
      }
    });
    return out;
  }

  var selectedRows = {};

  var optionLists = {
    doctor:   [],
    hospital: [],
    payer:    [],
    patient:  []
  };

  var els = {
    doctor:   document.getElementById("rpDoctor"),    // hidden input holding the selected value
    hospital: document.getElementById("rpHospital"),  // hidden input holding the selected value
    payer:    document.getElementById("rpPayer"),      // hidden input holding the selected value
    method:   document.getElementById("rpMethod"),
    fromDate: document.getElementById("rpFromDate"),
    toDate:   document.getElementById("rpToDate"),
    patient:  document.getElementById("rpPatient"),
    selectAll: document.getElementById("rpSelectAll"),
    tbody:    document.getElementById("rpTbody"),
    count:    document.getElementById("rpCount"),
    filteredCount: document.getElementById("rpFilteredCount"),
    gsPayments:   document.getElementById("rpGsPayments"),
    gsDoctors:    document.getElementById("rpGsDoctors"),
    gsHospitals:  document.getElementById("rpGsHospitals"),
    gsPaid:       document.getElementById("rpGsPaid"),
    gsAdjustment: document.getElementById("rpGsAdjustment"),
    gsBalance:    document.getElementById("rpGsBalance")
  };

  /* ---------------- helpers ---------------- */

  function safe(v){
    if(v === undefined || v === null) return "";
    if(Array.isArray(v)){
      // Some subform/lookup fields can come back as an array (e.g. multi-select
      // or a lookup wrapped in a list) — join whatever text we can find.
      return v.map(safe).filter(function(s){ return s !== ""; }).join(", ");
    }
    if(typeof v === "object"){
      if("display_value" in v && v.display_value !== null && v.display_value !== undefined) return String(v.display_value);
      if("zc_display_value" in v && v.zc_display_value !== null && v.zc_display_value !== undefined) return String(v.zc_display_value);
      if("value" in v && v.value !== null && v.value !== undefined) return String(v.value);
      if("ID" in v && v.ID !== null && v.ID !== undefined) return String(v.ID);
      if("id" in v && v.id !== null && v.id !== undefined) return String(v.id);
      return "";
    }
    return String(v);
  }

  function itemMatchKeys(value){
    var values = [];
    if(value && typeof value === "object" && !Array.isArray(value)){
      if(value.ID !== undefined && value.ID !== null) values.push("id:" + String(value.ID).trim());
      if(value.id !== undefined && value.id !== null) values.push("id:" + String(value.id).trim());
      if(value.display_value !== undefined && value.display_value !== null) values.push("text:" + String(value.display_value).trim().toLowerCase());
      if(value.zc_display_value !== undefined && value.zc_display_value !== null) values.push("text:" + String(value.zc_display_value).trim().toLowerCase());
      if(value.value !== undefined && value.value !== null) values.push("text:" + String(value.value).trim().toLowerCase());
    } else if(value !== undefined && value !== null){
      values.push("text:" + String(value).trim().toLowerCase());
    }
    return values.filter(function(key, index, keys){ return key !== "text:" && keys.indexOf(key) === index; });
  }

  function claimLineRows(claim){
  var rows = [];
  Object.keys(claim).forEach(function(k){
    var v = claim[k];
    if(Array.isArray(v) && v.length && v[0] && typeof v[0] === "object" &&
       (CLAIM_FIELD.itemCode in v[0])){
      v.forEach(function(li){
        rows.push({
          item: li[CLAIM_FIELD.itemCode],
          date: (CLAIM_FIELD.dateOfService in li) ? li[CLAIM_FIELD.dateOfService]
                                                  : claim[CLAIM_FIELD.dateOfService]
        });
      });
    }
  });
  if(!rows.length){
    rows.push({ item: claim[CLAIM_FIELD.itemCode], date: claim[CLAIM_FIELD.dateOfService] });
  }
  return rows;
}

// Returns all match keys (record id + text) for a Claim reference, wherever it sits in an object.
function claimRefKeys(obj){
  var keys = [];
  Object.keys(obj || {}).forEach(function(k){
    var v = obj[k];
    var text = safe(v);
    if(/^CLM-/i.test(text)){
      itemMatchKeys(v).forEach(function(key){ keys.push(key); });
    }
  });
  return keys.filter(function(k, i, a){ return a.indexOf(k) === i; });
}

// Finds the claim-lines subform on a claim record: the array whose rows contain Date_of_Service.
function findClaimLines(claim){
  var found = null;
  Object.keys(claim).forEach(function(k){
    var v = claim[k];
    if(!found && Array.isArray(v) && v.length && v[0] && typeof v[0] === "object" &&
       (CLAIM_FIELD.dateOfService in v[0])){
      found = v;
    }
  });
  return found || [];
}

function attachClaimServiceDates(paymentItems, claimRecords){
  var byClaimItem = {};   // "claimKey|itemKey" -> date of service
  var byClaim = {};       // "claimKey" -> date, only when all lines of the claim share one date

  claimRecords.forEach(function(claim){
    var cKeys = claimRefKeys(claim);
    if(claim.ID) cKeys.push("id:" + String(claim.ID).trim());
    var lines = findClaimLines(claim);
    var dates = {};

    lines.forEach(function(line){
      var d = safe(line[CLAIM_FIELD.dateOfService]);
      if(!d) return;
      dates[d] = true;
      var iKeys = itemMatchKeys(line[CLAIM_FIELD.itemCode]);
      cKeys.forEach(function(ck){
        iKeys.forEach(function(ik){
          var key = ck + "|" + ik;
          if(!byClaimItem.hasOwnProperty(key)) byClaimItem[key] = d;
        });
      });
    });

    var distinct = Object.keys(dates);
    if(distinct.length === 1){
      cKeys.forEach(function(ck){ byClaim[ck] = distinct[0]; });
    }
  });

  var unmatched = 0;
  paymentItems.forEach(function(item){
    var cKeys = claimRefKeys(item);
    var iKeys = itemMatchKeys(item[FIELD.itemCode]);
    var found = "";

    cKeys.forEach(function(ck){
      iKeys.forEach(function(ik){
        if(!found && byClaimItem.hasOwnProperty(ck + "|" + ik)) found = byClaimItem[ck + "|" + ik];
      });
    });
    if(!found){
      cKeys.forEach(function(ck){ if(!found && byClaim.hasOwnProperty(ck)) found = byClaim[ck]; });
    }

    item.dateOfService = found;
    if(!found) unmatched++;
  });

  console.log("Claims loaded:", claimRecords.length,
              "| claim|item keys:", Object.keys(byClaimItem).length,
              "| sample keys:", Object.keys(byClaimItem).slice(0, 4));
  console.log("First payment item claim keys:", paymentItems[0] ? claimRefKeys(paymentItems[0]) : "none");
  console.log("First claim record keys:", claimRecords[0] ? Object.keys(claimRecords[0]) : "none");
  console.log("First claim lines found:", claimRecords[0] ? findClaimLines(claimRecords[0]).length : 0);
  if(unmatched) console.warn(unmatched + " payment item(s) had no matching claim line.");
}

function toDateKey(zohoDateStr){
    if(!zohoDateStr) return "";
    var str = String(zohoDateStr).trim();
    var months = {
      jan:"01", feb:"02", mar:"03", apr:"04", may:"05", jun:"06",
      jul:"07", aug:"08", sep:"09", oct:"10", nov:"11", dec:"12"
    };
    // 1. DD-Mon-YYYY or DD-Mon-YY (Safari-safe custom match)
    var m1 = /^(\d{1,2})[-/ ]([A-Za-z]{3,9})[-/ ](\d{2,4})/.exec(str);
    if(m1){
      var mon = months[m1[2].slice(0, 3).toLowerCase()];
      if(mon){
        var yr = m1[3].length === 2 ? "20" + m1[3] : m1[3];
        var dy = String(m1[1]).padStart(2, "0");
        return yr + "-" + mon + "-" + dy;
      }
    }
    // 2. YYYY-MM-DD
    var m2 = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/.exec(str);
    if(m2){
      return m2[1] + "-" + String(m2[2]).padStart(2, "0") + "-" + String(m2[3]).padStart(2, "0");
    }
    // 3. DD/MM/YYYY or DD-MM-YYYY
    var m3 = /^(\d{1,2})[-/](\d{1,2})[-/](\d{4})/.exec(str);
    if(m3){
      return m3[3] + "-" + String(m3[2]).padStart(2, "0") + "-" + String(m3[1]).padStart(2, "0");
    }
    // 4. Fallback safe date parse
    var cleanIso = str.replace(/-/g, "/").split(".")[0];
    var d = new Date(cleanIso);
    if(!isNaN(d.getTime())){
      return d.getFullYear() + "-" + String(d.getMonth()+1).padStart(2,"0") + "-" + String(d.getDate()).padStart(2,"0");
    }
    return str;
  }

  function fmtMoney(n){
    var raw = safe(n).trim();
    if(raw === "") return "0.00";
    var cleaned = raw.replace(/[^0-9.\-]/g, "");
    var num = parseFloat(cleaned);
    if(isNaN(num)) return raw;
    return num.toLocaleString("en-IN", {minimumFractionDigits:2, maximumFractionDigits:2});
  }

  function uniqueSorted(arr){
    return Array.from(new Set(arr.filter(function(v){ return v && v.trim(); })))
                .sort(function(a,b){ return a.localeCompare(b); });
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, function(c){
      return ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c];
    });
  }

  function highlight(text, query){
    if(!query) return escapeHtml(text);
    var idx = text.toLowerCase().indexOf(query.toLowerCase());
    if(idx === -1) return escapeHtml(text);
    return escapeHtml(text.slice(0, idx)) +
           "<mark>" + escapeHtml(text.slice(idx, idx + query.length)) + "</mark>" +
           escapeHtml(text.slice(idx + query.length));
  }

  function fillDropdown(selectEl, values){
    var current = selectEl.value;
    while(selectEl.options.length > 1){ selectEl.remove(1); }
    values.forEach(function(v){
      var opt = document.createElement("option");
      opt.value = v; opt.textContent = v;
      selectEl.appendChild(opt);
    });
    if(values.indexOf(current) !== -1) selectEl.value = current;
  }

  function populateFilterOptions(){
    optionLists.doctor   = uniqueSorted(allRecords.map(function(r){ return safe(r[FIELD.doctor]); }));
    optionLists.hospital = uniqueSorted(allRecords.map(function(r){ return safe(r[FIELD.hospital]); }));
    optionLists.payer    = uniqueSorted(allRecords.map(function(r){ return safe(r[FIELD.payerName]); }));
    optionLists.patient  = uniqueSorted(allRecords.map(function(r){ return safe(r[FIELD.patient]); }));

    // Payment Method stays a plain dropdown, styled the same as the other
    // filters — populated dynamically from whatever methods actually exist in the data.
    fillDropdown(els.method, uniqueSorted(allRecords.map(function(r){ return safe(r[FIELD.method]); })));
  }

  /* ---------------- clear-button visibility ---------------- */

function refreshClearButtons(){
  document.querySelectorAll(".rp-field").forEach(function(field){
    if(field.id === "fld-doctor") return;   // locked field, no clear button
    var input = field.querySelector("select, input");
    field.classList.toggle("has-value", !!input.value);
  });
}

  document.querySelectorAll(".rp-clear-one").forEach(function(btn){
    btn.addEventListener("click", function(){
      var el = document.getElementById(btn.getAttribute("data-target"));
      el.value = "";
      // If this is a combo's hidden value field, also reset its visible label.
      if(el.dataset && el.dataset.label){
        var labelEl = document.getElementById(el.dataset.label);
        if(labelEl) labelEl.textContent = el.dataset.placeholder || "";
      }
      closeAllCombos();
      refreshClearButtons();
    });
  });

  [els.method, els.fromDate, els.toDate].forEach(function(el){
    el.addEventListener("change", refreshClearButtons);
    el.addEventListener("input", refreshClearButtons);
  });

  /* ---------------- searchable combo filter (Doctor / Hospital / Payer Name) ----------------
     Click the field to open a panel with a search box on top and a scrollable list
     below it (first row is the "All ___" option), matching the reference design. */

  var allCombos = [];

  function setupCombo(opts){
    var combo   = document.getElementById(opts.comboId);
    var btn     = document.getElementById(opts.btnId);
    var label   = document.getElementById(opts.labelId);
    var hidden  = document.getElementById(opts.hiddenId);
    var search  = document.getElementById(opts.searchId);
    var list    = document.getElementById(opts.listId);
    var listKey = opts.listKey;
    var placeholder = opts.placeholder;
    var activeIndex = -1;

    function filteredOptions(){
      var q = search.value.trim().toLowerCase();
      var all = optionLists[listKey] || [];
      if(!q) return all;
      return all.filter(function(v){ return v.toLowerCase().indexOf(q) !== -1; });
    }

    function renderList(){
      var q = search.value.trim();
      var matches = filteredOptions();
      activeIndex = -1;

      var html = '<div class="rp-combo-option rp-all" data-value="">' + placeholder + '</div>';
      if(matches.length){
        html += matches.slice(0, 50).map(function(v){
          return '<div class="rp-combo-option" data-value="' + escapeHtml(v) + '">' + highlight(v, q) + '</div>';
        }).join("");
      } else if(q){
        html += '<div class="rp-combo-empty">No matches</div>';
      }
      list.innerHTML = html;
    }

    function open(){
      closeAllCombos();
      search.value = "";
      renderList();
      combo.classList.add("rp-open");
      setTimeout(function(){ search.focus(); }, 0);
    }

    function close(){
      combo.classList.remove("rp-open");
      activeIndex = -1;
    }

    function selectValue(v){
      hidden.value = v;
      label.textContent = v ? v : placeholder;
      close();
      refreshClearButtons();
    }

    btn.addEventListener("click", function(e){
      e.stopPropagation();
      if(combo.classList.contains("rp-open")) close(); else open();
    });

    list.addEventListener("click", function(e){
      var opt = e.target.closest(".rp-combo-option");
      if(opt && !opt.classList.contains("rp-combo-empty")) selectValue(opt.getAttribute("data-value"));
    });

    search.addEventListener("input", renderList);
    search.addEventListener("click", function(e){ e.stopPropagation(); });

    search.addEventListener("keydown", function(e){
      var options = list.querySelectorAll(".rp-combo-option");
      if(!options.length) return;

      if(e.key === "ArrowDown"){
        e.preventDefault();
        activeIndex = Math.min(activeIndex + 1, options.length - 1);
        updateActive(options);
      } else if(e.key === "ArrowUp"){
        e.preventDefault();
        activeIndex = Math.max(activeIndex - 1, 0);
        updateActive(options);
      } else if(e.key === "Enter"){
        e.preventDefault();
        if(activeIndex >= 0 && options[activeIndex]){
          selectValue(options[activeIndex].getAttribute("data-value"));
        }
      } else if(e.key === "Escape"){
        close();
      }
    });

    function updateActive(options){
      options.forEach(function(o, i){ o.classList.toggle("rp-active", i === activeIndex); });
      if(options[activeIndex]) options[activeIndex].scrollIntoView({block:"nearest"});
    }

    document.addEventListener("click", function(e){
      if(!combo.contains(e.target)) close();
    });

    var api = {
      close: close,
      reset: function(){
        hidden.value = "";
        label.textContent = placeholder;
        close();
      }
    };
    allCombos.push(api);
    return api;
  }

  function closeAllCombos(){
    allCombos.forEach(function(c){ c.close(); });
  }
  setupCombo({
    comboId:"rpHospitalCombo", btnId:"rpHospitalBtn", labelId:"rpHospitalLabel", hiddenId:"rpHospital",
    searchId:"rpHospitalSearch", listId:"rpHospitalList", listKey:"hospital", placeholder:"All Hospitals"
  });
  setupCombo({
    comboId:"rpPayerCombo", btnId:"rpPayerBtn", labelId:"rpPayerLabel", hiddenId:"rpPayer",
    searchId:"rpPayerSearch", listId:"rpPayerList", listKey:"payer", placeholder:"All Payers"
  });
  setupCombo({
    comboId:"rpPatientCombo", btnId:"rpPatientBtn", labelId:"rpPatientLabel", hiddenId:"rpPatient",
    searchId:"rpPatientSearch", listId:"rpPatientList", listKey:"patient", placeholder:"All Patients"
  });

  /* ---------------- filtering ---------------- */

  function applyFilters(){
    var fDoctor   = els.doctor.value;     // exact value chosen from the combo list
    var fHospital = els.hospital.value;   // exact value chosen from the combo list
    var fPayer    = els.payer.value;      // exact value chosen from the combo list
    var fMethod   = els.method.value;     // exact match — plain dropdown
    var fFromDate = els.fromDate.value;   // yyyy-mm-dd
    var fToDate   = els.toDate.value;     // yyyy-mm-dd
    var fPatient  = els.patient.value;    // exact value chosen from the combo list

    viewRecords = allRecords.filter(function(r){
      if(fDoctor   && safe(r[FIELD.doctor])    !== fDoctor)   return false;
      if(fHospital && safe(r[FIELD.hospital])  !== fHospital) return false;
      if(fPayer    && safe(r[FIELD.payerName]) !== fPayer)    return false;
      if(fMethod   && safe(r[FIELD.method])    !== fMethod)   return false;

      var paymentDateKey = toDateKey(r[FIELD.paymentDate]);
      if(fFromDate && (!paymentDateKey || paymentDateKey < fFromDate)) return false;
      if(fToDate   && (!paymentDateKey || paymentDateKey > fToDate)) return false;

      if(fPatient  && safe(r[FIELD.patient])   !== fPatient)  return false;
      return true;
    });

    closeAllCombos();
    renderTable();
  }

  function resetAll(){
    allCombos.forEach(function(c){ c.reset(); });
    els.method.value = "";
    els.fromDate.value = "";
    els.toDate.value = "";
    refreshClearButtons();
    viewRecords = allRecords.slice();
    renderTable();
  }

  document.getElementById("rpApply").addEventListener("click", applyFilters);
  document.getElementById("rpResetAll").addEventListener("click", resetAll);

  /* ---------------- render ---------------- */

  function balanceTag(val){
    var num = parseFloat(val) || 0;
    var cls = num > 0 ? "due" : "clear";
    var label = num > 0 ? fmtMoney(num) : "Settled";
    return '<span class="rp-balance-tag ' + cls + '">' + label + '</span>';
  }

  // Groups the (already filtered) flat line-item rows back up by their parent
  // payment record, so the table can show Payment ID / Date / Method / Doctor /
  // Hospital once per payment, with the Payment_Items line items nested under it.
  function groupByPayment(list){
    var map = {};
    var order = [];
    list.forEach(function(r){
      // Payment ID should be unique per parent record; fall back to a
      // date+doctor+hospital composite in the rare case it's blank so rows
      // still group sensibly instead of each becoming its own group of one.
      var key = safe(r[FIELD.paymentId]) ||
        (safe(r[FIELD.paymentDate]) + "|" + safe(r[FIELD.doctor]) + "|" + safe(r[FIELD.hospital]));
      if(!map[key]){
        map[key] = { parent: r, items: [] };
        order.push(key);
      }
      map[key].items.push(r);
    });
    return order.map(function(k){ return map[k]; });
  }

  // Populates the Grand Summary card (Payments / Doctors / Hospitals /
  // Paid Amount / Adjustment Amount / Balance Due) from the currently
  // filtered dataset. Doctors/Hospitals are counted as distinct values
  // across the parent payment records, not per line item.
  function renderGrandSummary(list){
    var groups = groupByPayment(list);

    var doctorSet = {}, hospitalSet = {};
    var paid = 0, adjustment = 0, balance = 0;

    groups.forEach(function(g){
      var doc = safe(g.parent[FIELD.doctor]);
      var hosp = safe(g.parent[FIELD.hospital]);
      if(doc)  doctorSet[doc]   = true;
      if(hosp) hospitalSet[hosp] = true;
    });

    list.forEach(function(r){
      paid       += parseFloat(r[FIELD.allocated])  || 0;
      adjustment += parseFloat(r[FIELD.adjustment]) || 0;
      balance    += parseFloat(r[FIELD.balance])    || 0;
    });

    els.gsPayments.textContent   = groups.length;
    els.gsDoctors.textContent    = Object.keys(doctorSet).length;
    els.gsHospitals.textContent  = Object.keys(hospitalSet).length;
    els.gsPaid.textContent       = "$" + fmtMoney(paid);
    els.gsAdjustment.textContent = "$" + fmtMoney(adjustment);
    els.gsBalance.textContent    = "$" + fmtMoney(balance);
  }

  function renderTable(){
    renderGrandSummary(viewRecords);

    if(!viewRecords.length){
      els.tbody.innerHTML = '<tr><td colspan="12"><div class="rp-empty">No payments match the selected filters.</div></td></tr>';
      els.filteredCount.textContent = "0 records";
      updateSelectAllState();
      return;
    }

    var groups = groupByPayment(viewRecords);
    var html = "";

    groups.forEach(function(group){
      var parent = group.parent;
      var items = group.items;
      var rowspan = items.length;

      // Parent (main form) cells — rendered once, spanning every line-item
      // row that belongs to this payment.
      var parentCells =
        '<td class="rp-group-cell" rowspan="' + rowspan + '">' + safe(parent[FIELD.paymentId])   + "</td>" +
        '<td class="rp-group-cell" rowspan="' + rowspan + '">' + safe(parent[FIELD.paymentDate]) + "</td>" +
        '<td class="rp-group-cell" rowspan="' + rowspan + '">' + safe(parent[FIELD.method])      + "</td>" +
        '<td class="rp-group-cell" rowspan="' + rowspan + '">' + safe(parent[FIELD.doctor])      + "</td>" +
        '<td class="rp-group-cell" rowspan="' + rowspan + '">' + safe(parent[FIELD.hospital])    + "</td>";

      items.forEach(function(item, idx){
        html += '<tr class="rp-group-row' + (idx === 0 ? " rp-group-first" : "") + '">';
        var checked = selectedRows[item.__uid] ? " checked" : "";
        html += '<td><input type="checkbox" class="rp-row-check" data-uid="' + item.__uid + '"' + checked + "></td>";
        if(idx === 0) html += parentCells;
        html +=
          "<td>"  + safe(item[FIELD.patient])  + "</td>" +
          "<td>"  + safe(item.dateOfService) + "</td>" +
          "<td>"  + safe(item[FIELD.itemCode]) + "</td>" +
          '<td class="rp-amount">' + fmtMoney(item[FIELD.allocated])  + "</td>" +
          '<td class="rp-amount">' + fmtMoney(item[FIELD.adjustment]) + "</td>" +
          "<td>"  + balanceTag(item[FIELD.balance]) + "</td>" +
        "</tr>";
      });
    });

    els.tbody.innerHTML = html;
    els.filteredCount.textContent = groups.length + " payments (" + viewRecords.length + " of " + allRecords.length + " line items shown)";
    updateSelectAllState();
  }

  /* ---------------- claim selection (checkboxes / Select All / Export Selected) ---------------- */

  // Ticks/unticks a single claim's checkbox state, keyed by its stable __uid
  // so the selection survives re-renders caused by filtering.
  els.tbody.addEventListener("change", function(e){
    var cb = e.target.closest(".rp-row-check");
    if(!cb) return;
    var uid = cb.getAttribute("data-uid");
    if(cb.checked) selectedRows[uid] = true; else delete selectedRows[uid];
    updateSelectAllState();
  });

  // "Select All" only affects the claims currently visible under the active filters.
  els.selectAll.addEventListener("change", function(){
    var checked = els.selectAll.checked;
    viewRecords.forEach(function(r){
      if(checked) selectedRows[r.__uid] = true; else delete selectedRows[r.__uid];
    });
    renderTable();
  });

  // Keeps the header checkbox in sync (checked / unchecked / indeterminate)
  // with how many of the currently visible rows are selected.
  function updateSelectAllState(){
    if(!viewRecords.length){
      els.selectAll.checked = false;
      els.selectAll.indeterminate = false;
      return;
    }
    var selectedCount = 0;
    viewRecords.forEach(function(r){ if(selectedRows[r.__uid]) selectedCount++; });
    els.selectAll.checked = selectedCount === viewRecords.length;
    els.selectAll.indeterminate = selectedCount > 0 && selectedCount < viewRecords.length;
  }

 /* ---------------- export: excel ----------------
   Uses ExcelJS (not the plain xlsx/SheetJS writer) because SheetJS's free
   tier can't write cell styles — no bold header, no alignment, no widths.
   ExcelJS gives real column widths + right-aligned/number-formatted amount
   columns so the sheet looks correct the moment it opens, no manual
   resizing needed. */

var EXCEL_COLUMNS = [
  { header: "Payment ID",         key: "paymentId",   width: 14 },
  { header: "Payment Date",       key: "paymentDate", width: 16 },
  { header: "Payment Method",     key: "method",       width: 18 },
  { header: "Doctor",             key: "doctor",       width: 22 },
  { header: "Hospital",           key: "hospital",     width: 28 },
  { header: "Patient",            key: "patient",      width: 20 },
  { header: "Date of Service",    key: "dateOfService",width: 16 },
  { header: "Item Code",          key: "itemCode",     width: 14 },
  { header: "Allocated Amount",   key: "allocated",    width: 18 },
  { header: "Adjustment Amount",  key: "adjustment",   width: 18 },
  { header: "Balance Due",        key: "balance",      width: 14 }
];
var EXCEL_AMOUNT_KEYS = { allocated: true, adjustment: true, balance: true };
var EXCEL_COL_COUNT = EXCEL_COLUMNS.length;
var EXCEL_LAST_COL_LETTER = String.fromCharCode(64 + EXCEL_COL_COUNT);

// ---- helper: pull the currently-applied filter's display text ----------
// EDIT THESE to match your real filter controls (dropdown value/text,
// flatpickr instance, filter-state object, etc). Falling back to "All"
// keeps the export from breaking if a filter is untouched.
function getFilterText(elId, fallback){
  var el = document.getElementById(elId);
  if(!el) return fallback || "All";
  if(el.tagName === "SELECT"){
    return (el.options[el.selectedIndex] && el.options[el.selectedIndex].text) || fallback || "All";
  }
  return el.value || fallback || "All";
}

function formatGeneratedOn(){
  var d = new Date();
  var datePart = d.toLocaleDateString("en-GB", { day: "2-digit", month: "long", year: "numeric" });
  var timePart = d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", hour12: true }).toLowerCase();
  return datePart + ", " + timePart;
}

document.getElementById("rpExportExcel").addEventListener("click", function(){

  // ---- Helper: find the on-screen value for a filter by its visible label ----
  function getFilterValueByLabel(labelText){
    var allEls = document.querySelectorAll("div, span, label");
    for (var i = 0; i < allEls.length; i++){
      var el = allEls[i];
      if (el.children.length === 0 &&
          el.textContent.trim().toUpperCase() === labelText.toUpperCase()){

        var container = el.closest("div").parentElement;
        var candidates = [];
        if (el.nextElementSibling) candidates.push(el.nextElementSibling);
        if (container) candidates.push(container);

        for (var c = 0; c < candidates.length; c++){
          var holder = candidates[c];
          if (!holder) continue;

          var input = holder.querySelector("input");
          if (input && input.value && input.value.trim()){
            return input.value.trim();
          }

          var text = holder.textContent
            .replace(labelText, "")
            .trim();
          if (text) return text;
        }
      }
    }
    return "All";
  }

  function doctorLabel(){ return getFilterValueByLabel("DOCTOR") || "All"; }
  function hospitalLabel(){ return getFilterValueByLabel("HOSPITAL") || "All"; }
  function paymentMethodLabel(){ return getFilterValueByLabel("PAYMENT METHOD") || "All methods"; }
  function dateRangeLabel(){
    var from = els.fromDate && els.fromDate.value ? els.fromDate.value : "";
    var to = els.toDate && els.toDate.value ? els.toDate.value : "";
    if(from && to) return from + " to " + to;
    if(from) return "From " + from;
    if(to) return "Up to " + to;
    return "All";
  }

  var wb = new ExcelJS.Workbook();
  wb.creator = "Claims Management";
  var ws = wb.addWorksheet("Receipted Payments", {
    views: [{ state: "frozen", ySplit: 6 }]
  });
  ws.columns = EXCEL_COLUMNS;

  var headerOpts = {
    reportTitle: "Payment Report",
    fields: [
      { label: "Doctor",       value: doctorLabel() },
      { label: "Payment Type", value: paymentMethodLabel() },
      { label: "Payment Date", value: dateRangeLabel() },
      { label: "Generated On", value: new Date().toLocaleString() }
    ]
  };

  // ================= Row 1: report title bar =================
  var titleRow = ws.getRow(1);
  titleRow.height = 26;
  ws.mergeCells(1, 1, 1, EXCEL_COL_COUNT);
  var titleCell = titleRow.getCell(1);
  titleCell.value = headerOpts.reportTitle;
  titleCell.font = { bold: true, size: 14, color: { argb: "FF1F2A44" } };
  titleCell.alignment = { vertical: "middle", horizontal: "left", indent: 1 };
  titleRow.eachCell({ includeEmpty: true }, function(cell){
    cell.border = {
      top:    { style: "medium", color: { argb: "FF0E6E63" } },
      bottom: { style: "medium", color: { argb: "FF0E6E63" } },
      left:   { style: "medium", color: { argb: "FF0E6E63" } },
      right:  { style: "medium", color: { argb: "FF0E6E63" } }
    };
  });

  // Row 2: blank spacer
  ws.getRow(2).height = 6;

  // ================= Row 3 & 4: filter labels + values =================
  // Each filter field gets a merged 2-column block so long values
  // (e.g. "All methods") can't visually spill into the next field.
  var FIELD_SPAN = 2; // columns per field
  var labelRow = ws.getRow(3);
  var valueRow = ws.getRow(4);
  valueRow.height = 18;

  headerOpts.fields.forEach(function(field, i){
    var startCol = i * FIELD_SPAN + 1;
    var endCol = startCol + FIELD_SPAN - 1;

    // Label cell (merged)
    ws.mergeCells(3, startCol, 3, endCol);
    var labelCell = labelRow.getCell(startCol);
    labelCell.value = field.label.toUpperCase();
    labelCell.font = { bold: true, size: 9, color: { argb: "FF0E6E63" } };
    labelCell.alignment = { vertical: "middle", horizontal: "left" };

    // Value cell (merged)
    ws.mergeCells(4, startCol, 4, endCol);
    var valueCell = valueRow.getCell(startCol);
    valueCell.value = field.value || "All";
    valueCell.font = { bold: true, size: 11, color: { argb: "FF1F2A44" } };
    valueCell.alignment = { vertical: "middle", horizontal: "left" };
  });

  // Row 5: blank spacer before the data table
  ws.getRow(5).height = 8;

  // ================= Row 6: table header =================
  var headerRow = ws.getRow(6);
  headerRow.height = 20;
  EXCEL_COLUMNS.forEach(function(col, i){
    var cell = headerRow.getCell(i + 1);
    cell.value = col.header;
    cell.font = { bold: true, color: { argb: "FFFFFFFF" } };
    cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF0E6E63" } };
    cell.alignment = { vertical: "middle", horizontal: "center" };
    cell.border = { bottom: { style: "thin", color: { argb: "FF0A5148" } } };
  });

  // ================= Data rows (starting row 7) =================
  // Grouped by payment/claim, mirroring the on-screen table: the parent
  // payment fields (Payment ID, Payment Date, Payment Method, Doctor,
  // Hospital) are written once per group and vertically merged across
  // every line-item row that belongs to that payment, instead of being
  // repeated on every row.
  var PARENT_COL_COUNT = 5; // Payment ID, Payment Date, Payment Method, Doctor, Hospital
  var excelGroups = groupByPayment(viewRecords);

  excelGroups.forEach(function(group){
    var parent = group.parent;
    var items = group.items;
    var groupStartRow = ws.rowCount + 1;

    items.forEach(function(item, idx){
      var row = ws.addRow({
        paymentId:   idx === 0 ? safe(parent[FIELD.paymentId])   : "",
        paymentDate: idx === 0 ? safe(parent[FIELD.paymentDate]) : "",
        method:      idx === 0 ? safe(parent[FIELD.method])      : "",
        doctor:      idx === 0 ? safe(parent[FIELD.doctor])      : "",
        hospital:    idx === 0 ? safe(parent[FIELD.hospital])    : "",
        patient:     safe(item[FIELD.patient]),
        dateOfService: safe(item.dateOfService),
        itemCode:    safe(item[FIELD.itemCode]),
        allocated:   parseFloat(item[FIELD.allocated])  || 0,
        adjustment:  parseFloat(item[FIELD.adjustment]) || 0,
        balance:     parseFloat(item[FIELD.balance])    || 0
      });

      EXCEL_COLUMNS.forEach(function(col, i){
        var cell = row.getCell(i + 1);
        if(EXCEL_AMOUNT_KEYS[col.key]){
          cell.numFmt = "#,##0.00";
          cell.alignment = { vertical: "middle", horizontal: "right" };
        } else {
          cell.alignment = { vertical: "middle", horizontal: "left" };
        }
        cell.border = { bottom: { style: "hair", color: { argb: "FFDDE4EA" } } };
      });
    });

    var groupEndRow = ws.rowCount;
    if(items.length > 1){
      for(var pc = 1; pc <= PARENT_COL_COUNT; pc++){
        ws.mergeCells(groupStartRow, pc, groupEndRow, pc);
        var mergedCell = ws.getCell(groupStartRow, pc);
        mergedCell.alignment = { vertical: "middle", horizontal: "left" };
      }
    }
  });

  // ================= Grand Summary card (after the last data row) =================
  // Mirrors the on-screen "Grand Summary" card: a title bar over a 6-item
  // grid (Payments / Doctors / Hospitals / Paid / Adjustment / Balance),
  // using the same palette (--ink #12212E top bar & title, --ink-soft
  // #4C6072 labels, --brand-dark #0A5148 for money, --red #B3261E for
  // balance due, card fill #EEF3FB, border #D7E0EF).
  var gsGroups = groupByPayment(viewRecords);
  var gsDoctorSet = {}, gsHospitalSet = {};
  gsGroups.forEach(function(g){
    var doc = safe(g.parent[FIELD.doctor]);
    var hosp = safe(g.parent[FIELD.hospital]);
    if(doc)  gsDoctorSet[doc]   = true;
    if(hosp) gsHospitalSet[hosp] = true;
  });
  var grandAllocated = 0, grandAdjustment = 0, grandBalance = 0;
  viewRecords.forEach(function(r){
    grandAllocated  += parseFloat(r[FIELD.allocated])  || 0;
    grandAdjustment += parseFloat(r[FIELD.adjustment]) || 0;
    grandBalance    += parseFloat(r[FIELD.balance])    || 0;
  });

  var GS_ITEMS = [
    { label: "Payments",          value: gsGroups.length,                     money: false },
    { label: "Doctors",           value: Object.keys(gsDoctorSet).length,     money: false },
    { label: "Hospitals",         value: Object.keys(gsHospitalSet).length,   money: false },
    { label: "Paid Amount",       value: grandAllocated,  money: true, color: "FF0A5148" },
    { label: "Adjustment Amount", value: grandAdjustment, money: true, color: "FF0A5148" },
    { label: "Balance Due",       value: grandBalance,    money: true, color: "FFB3261E" }
  ];
  var GS_SPANS = [2, 1, 1, 2, 2, 2]; // adds up to EXCEL_COL_COUNT (10)
  var GS_FILL = "FFEEF3FB";
  var GS_BORDER = "FFD7E0EF";

  ws.getRow(ws.rowCount + 1).height = 10; // spacer before the card

  // Title row, with the dark top accent bar the on-screen card has via ::before
  var gsTitleRowNum = ws.rowCount + 1;
  var gsTitleRow = ws.getRow(gsTitleRowNum);
  gsTitleRow.height = 24;
  ws.mergeCells(gsTitleRowNum, 1, gsTitleRowNum, EXCEL_COL_COUNT);
  var gsTitleCell = gsTitleRow.getCell(1);
  gsTitleCell.value = "GRAND SUMMARY";
  gsTitleCell.font = { bold: true, size: 12, color: { argb: "FF12212E" } };
  gsTitleCell.alignment = { vertical: "middle", horizontal: "left", indent: 1 };
  gsTitleRow.eachCell({ includeEmpty: true }, function(cell){
    cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: GS_FILL } };
    cell.border = { top: { style: "medium", color: { argb: "FF12212E" } }, left: { style: "thin", color: { argb: GS_BORDER } }, right: { style: "thin", color: { argb: GS_BORDER } } };
  });

  // Label row + value row, laid out as a 6-item grid across the columns
  var gsLabelRowNum = gsTitleRowNum + 1;
  var gsValueRowNum = gsLabelRowNum + 1;
  var gsLabelRow = ws.getRow(gsLabelRowNum);
  var gsValueRow = ws.getRow(gsValueRowNum);
  gsLabelRow.height = 16;
  gsValueRow.height = 24;

  var gsCol = 1;
  GS_ITEMS.forEach(function(item, i){
    var startCol = gsCol;
    var endCol = startCol + GS_SPANS[i] - 1;

    ws.mergeCells(gsLabelRowNum, startCol, gsLabelRowNum, endCol);
    var labelCell = gsLabelRow.getCell(startCol);
    labelCell.value = item.label.toUpperCase();
    labelCell.font = { bold: true, size: 8, color: { argb: "FF4C6072" } };
    labelCell.alignment = { vertical: "middle", horizontal: "left", indent: 1 };

    ws.mergeCells(gsValueRowNum, startCol, gsValueRowNum, endCol);
    var valueCell = gsValueRow.getCell(startCol);
    valueCell.value = item.value;
    if(item.money) valueCell.numFmt = "$#,##0.00";
    valueCell.font = { bold: true, size: 13, color: { argb: item.color || "FF12212E" } };
    valueCell.alignment = { vertical: "middle", horizontal: "left", indent: 1 };

    gsCol = endCol + 1;
  });

  [gsLabelRow, gsValueRow].forEach(function(row, idx){
    row.eachCell({ includeEmpty: true }, function(cell){
      cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: GS_FILL } };
      var isLast = idx === 1; // value row = bottom edge of the card
      cell.border = {
        left:   { style: "thin", color: { argb: GS_BORDER } },
        right:  { style: "thin", color: { argb: GS_BORDER } },
        bottom: isLast ? { style: "thin", color: { argb: GS_BORDER } } : undefined
      };
    });
  });

  ws.autoFilter = { from: "A6", to: EXCEL_LAST_COL_LETTER + "6" };

  wb.xlsx.writeBuffer().then(async function(buffer){
    var blob = new Blob([buffer], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    await handleFileExport(blob, "Receipted_Payments.xlsx", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "excel");
  }).catch(function(err){
    console.error("Excel export failed:", err);
    showToast("Excel export failed: " + (err.message || err));
  });
});

document.getElementById("rpExportPdf").addEventListener("click", async function () {
  var exportRecords = viewRecords.filter(function(r){ return !!selectedRows[r.__uid]; });
  if(!exportRecords.length) exportRecords = viewRecords;

  var jsPDF = window.jspdf.jsPDF;
  var doc = new jsPDF({ orientation: "landscape", unit: "pt", format: "a4" });

  var pageWidth = doc.internal.pageSize.getWidth();   // 595.28pt
  var pageHeight = doc.internal.pageSize.getHeight(); // 841.89pt
  var margin = 20;

  var BRAND = {
    navy: [27, 45, 79],
    slate: [76, 96, 114],
    slateLight: [140, 152, 165],
    hairline: [223, 228, 233],
    tableHeadFill: [14, 110, 99],
    green: [33, 122, 84]   // <-- add this line
};

  var HEADER_H = 158;
  var FOOTER_H = 70;
  var LOGO_IMG = "data:image/png;base64,";
  var LOGO_NATIVE_W = 479;
  var LOGO_NATIVE_H = 285;

  function drawLogoBadge(doc, x, y, w) {
    var h = w * (LOGO_NATIVE_H / LOGO_NATIVE_W);
    doc.addImage(LOGO_IMG, "PNG", x, y, w, h);
    return h;
  }

  // ================= ICONS =================
  function iconPerson(doc, x, y, s, color) {
    doc.setDrawColor.apply(doc, color); doc.setLineWidth(1.1);
    doc.circle(x + s * 0.5, y + s * 0.28, s * 0.22, "S");
    doc.lines(
      [[s * 0.68, 0], [0, -s * 0.05], [-s * 0.10, -s * 0.28], [-s * 0.48, 0], [-s * 0.10, s * 0.28]],
      x + s * 0.16, y + s * 0.95, [1, 1], "S", true
    );
  }
  function iconHospital(doc, x, y, s, color) {
    doc.setDrawColor.apply(doc, color); doc.setLineWidth(1.1);
    doc.rect(x, y + s * 0.15, s, s * 0.75, "S");
    doc.line(x + s * 0.5, y + s * 0.32, x + s * 0.5, y + s * 0.62);
    doc.line(x + s * 0.35, y + s * 0.47, x + s * 0.65, y + s * 0.47);
  }
  function iconCalendar(doc, x, y, s, color) {
    doc.setDrawColor.apply(doc, color); doc.setLineWidth(1.1);
    doc.roundedRect(x, y + s * 0.15, s, s * 0.75, 1.5, 1.5, "S");
    doc.line(x, y + s * 0.4, x + s, y + s * 0.4);
    doc.line(x + s * 0.25, y + s * 0.05, x + s * 0.25, y + s * 0.25);
    doc.line(x + s * 0.75, y + s * 0.05, x + s * 0.75, y + s * 0.25);
  }
  function iconClock(doc, x, y, s, color) {
    doc.setDrawColor.apply(doc, color); doc.setLineWidth(1.1);
    doc.circle(x + s / 2, y + s / 2, s / 2 - 1, "S");
    doc.line(x + s / 2, y + s / 2, x + s / 2, y + s * 0.28);
    doc.line(x + s / 2, y + s / 2, x + s * 0.68, y + s / 2);
  }
var ICON_PHONE_IMG = "data:image/png;base64,"; 
// Green padlock-in-rounded-square icon (replaces the old flag/triangle shape)
var ICON_SHIELD_IMG = "data:image/png;base64,";
 
function iconPhone(doc, x, y, s, color) {
  var w = s;
  var h = s * 0.68;
  var dy = (s - h) / 2;
  doc.addImage(ICON_PHONE_IMG, "PNG", x, y + dy, w, h);
}
 function iconMail(doc, x, y, s, color) {
    doc.setDrawColor.apply(doc, color); doc.setLineWidth(1.2);
    doc.roundedRect(x, y + s * 0.16, s, s * 0.68, 1, 1, "S");
    doc.lines(
      [[s * 0.5, s * 0.34], [s * 0.5, -s * 0.34]],
      x, y + s * 0.16, [1, 1], "S", false
    );
}
  function iconGlobe(doc, x, y, s, color) {
    doc.setDrawColor.apply(doc, color); doc.setLineWidth(1.1);
    doc.circle(x + s / 2, y + s / 2, s / 2 - 1, "S");
    doc.line(x + 1, y + s / 2, x + s - 1, y + s / 2);
    doc.line(x + s / 2, y + 1, x + s / 2, y + s - 1);
    doc.ellipse(x + s / 2, y + s / 2, s * 0.18, s / 2 - 1, "S");
}
  function iconShield(doc, x, y, s, color) {
  // color param kept for call-site compatibility but is not used —
  // the icon is pre-colored to match brand green.
  doc.addImage(ICON_SHIELD_IMG, "PNG", x, y, s, s);
}

  function truncateToWidth(doc, text, maxWidth) {
    text = String(text == null ? "" : text);
    if (doc.getTextWidth(text) <= maxWidth) return text;
    var ell = "\u2026";
    var out = text;
    while (out.length > 0 && doc.getTextWidth(out + ell) > maxWidth) {
      out = out.slice(0, -1);
    }
    return out.length ? out + ell : ell;
  }

  function metaField(doc, x, y, label, value, iconFn, maxWidth) {
    iconFn(doc, x, y, 13, [33, 122, 84]);
    doc.setFont(undefined, "bold");
    doc.setFontSize(6.3);
    doc.setTextColor.apply(doc, BRAND.slateLight);
    doc.text(label.toUpperCase(), x + 18, y + 6);
    doc.setFont(undefined, "normal");
    doc.setFontSize(8.5);
    doc.setTextColor.apply(doc, BRAND.navy);
    var displayValue = (value == null || value === "") ? "\u2014" : value;
    if (maxWidth) displayValue = truncateToWidth(doc, displayValue, maxWidth - 18);
    doc.text(String(displayValue), x + 18, y + 17);
  }

  function drawHeader(doc, opts) {
    var x0 = margin;

    // Larger logo (was 92pt wide) — header height/line/field positions
    // below are sized to fit it without crowding the rest of the header.
    var logoH = drawLogoBadge(doc, x0, 8, 130);

    doc.setFont(undefined, "bold");
    doc.setFontSize(15);
    doc.setTextColor.apply(doc, BRAND.navy);
    doc.text(opts.reportTitle || "REPORT", pageWidth - margin, 46, { align: "right" });

    var lineY = 8 + logoH + 12;
    doc.setDrawColor(33, 122, 84);
    doc.setLineWidth(1.4);
    doc.line(x0, lineY, pageWidth - margin, lineY);

    var fieldsY = lineY + 22;
    var fields = opts.fields;
    var colGap = 10;
    var colW = (pageWidth - margin * 2) / fields.length;
    fields.forEach(function (f, i) {
      // Reserve a small gap on the right of each field's slot so a long
      // value never runs into the next field's label.
      metaField(doc, x0 + i * colW, fieldsY, f.label, f.value, f.icon, colW - colGap);
    });

    var hairlineY = fieldsY + 28;
    doc.setDrawColor.apply(doc, BRAND.hairline);
    doc.setLineWidth(0.7);
    doc.line(x0, hairlineY, pageWidth - margin, hairlineY);
  }

  // ================= footer (matches sample: title+page row, notice
  // paragraph, centered contact icon row) =================
  function drawFooter(doc, pageNum, pageCount, opts) {
    var top = pageHeight - FOOTER_H;
    doc.setDrawColor.apply(doc, BRAND.hairline);
    doc.setLineWidth(0.7);
    doc.line(margin, top, pageWidth - margin, top);

    iconShield(doc, margin, top + 8, 11, BRAND.slate);
    doc.setFont(undefined, "bold");
    doc.setFontSize(7.2);
    doc.setTextColor.apply(doc, BRAND.navy);
    doc.text((opts.confidentialTitle || "CONFIDENTIAL").toUpperCase(), margin + 16, top + 16);

    doc.setFont(undefined, "normal");
    doc.setFontSize(7.5);
    doc.setTextColor.apply(doc, BRAND.slate);
    doc.text("Page " + pageNum + " of " + pageCount, pageWidth - margin, top + 16, { align: "right" });

    doc.setFontSize(6.2);
    doc.setTextColor.apply(doc, BRAND.slateLight);
    var noticeLines = doc.splitTextToSize(opts.confidentialNote || "", pageWidth - margin * 2);
    doc.text(noticeLines.slice(0, 2), margin, top + 27);

    // contact row, centered as a group (icon + text triples, evenly gapped)
   // contact row, centered as a group (icon + text triples, evenly gapped)
   var contacts = [
      { icon: iconPhone, text: opts.phone, color: BRAND.green },
      { icon: iconMail, text: opts.email, color: BRAND.green },
      { icon: iconGlobe, text: opts.website, color: BRAND.green }
    ].filter(function (c) { return c.text; });

    doc.setFont(undefined, "normal");
    doc.setFontSize(7);
    var widths = contacts.map(function (c) { return 16 + doc.getTextWidth(c.text); });
    var gap = 26;
    var totalW = widths.reduce(function (a, b) { return a + b; }, 0) + gap * (contacts.length - 1);
    var cx = (pageWidth - totalW) / 2;
    contacts.forEach(function (c, i) {
      c.icon(doc, cx, top + 44, 12, c.color);
      doc.setTextColor.apply(doc, BRAND.slate);
      doc.text(c.text, cx + 16, top + 53);
      cx += widths[i] + gap;
    });

    doc.setFont(undefined, "normal");          // ← delete from here...
    doc.setFontSize(7);
    var widths = contacts.map(function (c) { return 16 + doc.getTextWidth(c.text); });
    var gap = 26;
    var totalW = widths.reduce(function (a, b) { return a + b; }, 0) + gap * (contacts.length - 1);
    var cx = (pageWidth - totalW) / 2;
    contacts.forEach(function (c, i) {
      c.icon(doc, cx, top + 44, 12, c.color);
      doc.setTextColor.apply(doc, BRAND.slate);
      doc.text(c.text, cx + 16, top + 53);
      cx += widths[i] + gap;
    });
  
  }                                             // ← ...to here

  var GS_FILL = [238, 243, 251];   // #eef3fb
  var GS_BORDER = [215, 224, 239]; // #d7e0ef
  var GS_INK = [18, 33, 46];       // #12212e
  var GS_INK_SOFT = [76, 96, 114]; // #4c6072
  var GS_BRAND_DARK = [10, 81, 72];  // #0a5148
  var GS_RED = [179, 38, 30];        // #b3261e

  function grandSummaryCardHeight() {
    return 78;
  }

  function drawGrandSummaryCard(doc, x, y, w, items) {
    var h = grandSummaryCardHeight();
    var r = 6;

    doc.setFillColor.apply(doc, GS_FILL);
    doc.roundedRect(x, y, w, h, r, r, "F");
    doc.setDrawColor.apply(doc, GS_BORDER);
    doc.setLineWidth(0.75);
    doc.roundedRect(x, y, w, h, r, r, "S");

    // top accent bar (rounded to match the card's top corners)
    doc.setFillColor.apply(doc, GS_INK);
    doc.roundedRect(x, y, w, 8, r, r, "F");
    doc.rect(x, y + 4, w, 4, "F");

    var padX = 16;
    doc.setFont(undefined, "bold");
    doc.setFontSize(11);
    doc.setTextColor.apply(doc, GS_INK);
    doc.text("GRAND SUMMARY", x + padX, y + 26);

    var colGap = 12;
    var colW = (w - padX * 2 - colGap * (items.length - 1)) / items.length;
    var itemY = y + 42;

    items.forEach(function (item, i) {
      var itemX = x + padX + i * (colW + colGap);

      doc.setFont(undefined, "bold");
      doc.setFontSize(7);
      doc.setTextColor.apply(doc, GS_INK_SOFT);
      doc.text(item.label.toUpperCase(), itemX, itemY);

      doc.setFont(undefined, "bold");
      doc.setFontSize(13);
      doc.setTextColor.apply(doc, item.color || GS_INK);
      doc.text(String(item.value), itemX, itemY + 18);
    });

    return h;
  }
  function singleSharedValue(records, getter) {
    var seen = {};
    var count = 0;
    for (var i = 0; i < records.length; i++) {
      var v = getter(records[i]);
      if (!v) continue;
      if (!seen[v]) { seen[v] = true; count++; }
      if (count > 1) return null;
    }
    return count === 1 ? Object.keys(seen)[0] : null;
  }

  function doctorLabel() {
    return singleSharedValue(exportRecords, function (r) { return safe(r[FIELD.doctor]); }) || "All Doctors";
  }
  function hospitalLabel() {
    return singleSharedValue(exportRecords, function (r) { return safe(r[FIELD.hospital]); }) || "All Hospitals";
  }
  function dateRangeLabel() {
    var from = els.fromDate && els.fromDate.value ? els.fromDate.value : "";
    var to = els.toDate && els.toDate.value ? els.toDate.value : "";
    if(from && to) return from + " to " + to;
    if(from) return "From " + from;
    if(to) return "Up to " + to;
    return "All Payment Dates";
  }

  var head = [[
    "Payment ID", "Payment Date", "Payment Method", "Doctor", "Hospital", "Patient",
    "Date of Service", "Item Code", "Allocated Amount", "Adjustment Amount", "Balance Due"
  ]];

  // Grouped by payment/claim, mirroring the on-screen table: the parent
  // payment cells (Payment ID, Payment Date, Payment Method, Doctor,
  // Hospital) are drawn once per group using autoTable's rowSpan, instead
  // of being repeated on every line-item row.
  var pdfBodyGroups = groupByPayment(exportRecords);
  var body = [];
  pdfBodyGroups.forEach(function (g) {
    var parent = g.parent;
    var items = g.items;
    var rowspan = items.length;

    items.forEach(function (item, idx) {
      var row = [];
      if (idx === 0) {
        row.push({ content: safe(parent[FIELD.paymentId]),   rowSpan: rowspan, styles: { valign: "middle", fillColor: [255, 255, 255], textColor: [0, 0, 0] },lineColor: [210, 210, 210],lineWidth: 0.5 });
        row.push({ content: safe(parent[FIELD.paymentDate]), rowSpan: rowspan, styles: { valign: "middle", fillColor: [255, 255, 255], textColor: [0, 0, 0] } });
        row.push({ content: safe(parent[FIELD.method]),      rowSpan: rowspan, styles: { valign: "middle", fillColor: [255, 255, 255], textColor: [0, 0, 0] } });
        row.push({ content: safe(parent[FIELD.doctor]),      rowSpan: rowspan, styles: { valign: "middle", fillColor: [255, 255, 255], textColor: [0, 0, 0] } });
        row.push({ content: safe(parent[FIELD.hospital]),    rowSpan: rowspan, styles: { valign: "middle", fillColor: [255, 255, 255], textColor: [0, 0, 0] } });
      }
      row.push(safe(item[FIELD.patient]));
      row.push(safe(item.dateOfService));
      row.push(safe(item[FIELD.itemCode]));
      row.push(fmtMoney(item[FIELD.allocated]));
      row.push(fmtMoney(item[FIELD.adjustment]));
      row.push(fmtMoney(item[FIELD.balance]));
      body.push(row);
    });
  });

  var headerOpts = {
    reportTitle: "RECEIPTED PAYMENTS",
    fields: [
      { label: "Doctor", value: doctorLabel(), icon: iconPerson },
      { label: "Hospital", value: hospitalLabel(), icon: iconHospital },
      { label: "Payment Date", value: dateRangeLabel(), icon: iconCalendar },
      { label: "Generated On", value: new Date().toLocaleString(), icon: iconClock }
    ]
  };

  var footerOpts = {
  confidentialTitle: "Confidential \u2013 Contains Sensitive Health Information",
  confidentialNote: "This document contains confidential patient and billing information and is intended only for the named recipient and authorised personnel. Unauthorised access, use, copying, forwarding or disclosure is prohibited. If you received this document in error, please notify Medi Elves immediately, delete all electronic copies, and destroy any hard copies.",
  phone: "1800 956 692",
  email: "admin@medielves.com.au",
  website: "www.medielves.com.au"
};

  var MONEY_COLS = [8, 9, 10]; // Allocated Amount, Adjustment Amount, Balance Due

  doc.autoTable({
    head: head,
    body: body,
    startY: HEADER_H,
    margin: { left: margin, right: margin, top: HEADER_H, bottom: FOOTER_H },
    tableWidth: pageWidth - margin * 2,
    styles: {
      fontSize: 6.5,
      cellPadding: 3,
      overflow: "linebreak",
      valign: "middle",
      fillColor: [255, 255, 255],
      textColor: [0, 0, 0],
      lineColor: [210, 210, 210],
      lineWidth: 0.5
    },
    headStyles: { fillColor: BRAND.tableHeadFill, textColor: [255, 255, 255], halign: "left", fontSize: 6.5 },
    didParseCell: function (data) {
      if (data.section === "body") {
        data.cell.styles.fillColor = [255, 255, 255];
        data.cell.styles.textColor = [0, 0, 0];
        data.cell.styles.lineColor = [210, 210, 210];
        data.cell.styles.lineWidth = 0.5;
      }

      if (MONEY_COLS.indexOf(data.column.index) !== -1) {
        data.cell.styles.halign = "right";
      }
    },
    didDrawPage: function () {
      drawHeader(doc, headerOpts);
    }
  });

  // ---- Grand Summary card: totals across every exported line item (selected claims, or all if none selected) ----
  var pdfGroups = groupByPayment(exportRecords);
  var pdfDoctorSet = {}, pdfHospitalSet = {};
  pdfGroups.forEach(function (g) {
    var d = safe(g.parent[FIELD.doctor]);
    var h = safe(g.parent[FIELD.hospital]);
    if (d) pdfDoctorSet[d] = true;
    if (h) pdfHospitalSet[h] = true;
  });
  var grandAllocated = 0, grandAdjustment = 0, grandBalance = 0;
  exportRecords.forEach(function (r) {
    grandAllocated  += parseFloat(r[FIELD.allocated])  || 0;
    grandAdjustment += parseFloat(r[FIELD.adjustment]) || 0;
    grandBalance    += parseFloat(r[FIELD.balance])    || 0;
  });

  var GS_ITEMS = [
    { label: "Payments",          value: pdfGroups.length },
    { label: "Doctors",           value: Object.keys(pdfDoctorSet).length },
    { label: "Hospitals",         value: Object.keys(pdfHospitalSet).length },
    { label: "Paid Amount",       value: "$" + fmtMoney(grandAllocated),  color: GS_BRAND_DARK },
    { label: "Adjustment Amount", value: "$" + fmtMoney(grandAdjustment), color: GS_BRAND_DARK },
    { label: "Balance Due",       value: "$" + fmtMoney(grandBalance),    color: GS_RED }
  ];

  var cardGap = 16;
  var cardH = grandSummaryCardHeight();
  var cardY = doc.lastAutoTable.finalY + cardGap;

  if (cardY + cardH > pageHeight - FOOTER_H) {
    doc.addPage();
    drawHeader(doc, headerOpts);
    cardY = HEADER_H + cardGap;
  }

  drawGrandSummaryCard(doc, margin, cardY, pageWidth - margin * 2, GS_ITEMS);

  var pageCount = doc.internal.getNumberOfPages();
  for (var p = 1; p <= pageCount; p++) {
    doc.setPage(p);
    drawFooter(doc, p, pageCount, footerOpts);
  }

  var pdfBlob = doc.output("blob");
  await handleFileExport(pdfBlob, "Receipted_Payments.pdf", "application/pdf", "pdf", doc);
});

/* =================================================================
   ZOHO CREATOR MODULE REPORT EXPORT & DIRECT DOWNLOAD HELPERS
   Form: Report_Export
   Report: All_Report_Exports
   Fields: Export_PDF / Export_Excel
   ================================================================= */
var REPORT_EXPORT_FORM = "Report_Export";
var REPORT_EXPORT_VIEW = "All_Report_Exports";
var REPORT_EXPORT_PDF_FIELD = "Export_PDF";
var REPORT_EXPORT_EXCEL_FIELD = "Export_Excel";
var LOCAL_STORAGE_PDF_KEY = "rp_saved_pdf";
var LOCAL_STORAGE_EXCEL_KEY = "rp_saved_excel";

function isMobileDevice() {
  var ua = navigator.userAgent || navigator.vendor || window.opera || "";
  return /android|iphone|ipad|ipod|blackberry|iemobile|opera mini/i.test(ua) ||
         (navigator.maxTouchPoints && navigator.maxTouchPoints > 2 && /Macintosh/i.test(ua));
}

function isIOS() {
  var ua = navigator.userAgent || navigator.vendor || window.opera || "";
  return /iphone|ipad|ipod/i.test(ua) ||
         (navigator.maxTouchPoints && navigator.maxTouchPoints > 2 && /Macintosh/i.test(ua));
}

function formatBytes(bytes) {
  if (!bytes || bytes === 0) return "0 KB";
  var k = 1024;
  var sizes = ["Bytes", "KB", "MB", "GB"];
  var i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
}

function getPortalBaseUrl() {
  if (document.referrer) {
    try {
      var refUrl = new URL(document.referrer);
      if (refUrl.origin && !refUrl.origin.includes("zohocdn")) {
        return refUrl.origin;
      }
    } catch (e) {}
  }
  if (window.location && window.location.origin && !window.location.origin.includes("zohocdn")) {
    return window.location.origin;
  }
  return "https://portal.medielves.com.au";
}

function extractRecordId(resp) {
  if (!resp) return null;
  if (resp.data) {
    if (resp.data.ID) return String(resp.data.ID);
    if (resp.data.id) return String(resp.data.id);
  }
  if (resp.result) {
    if (Array.isArray(resp.result) && resp.result[0]) {
      if (resp.result[0].ID) return String(resp.result[0].ID);
      if (resp.result[0].id) return String(resp.result[0].id);
    }
    if (resp.result.ID) return String(resp.result.ID);
    if (resp.result.id) return String(resp.result.id);
  }
  if (resp.ID) return String(resp.ID);
  if (resp.id) return String(resp.id);
  return null;
}

// Upload file to Zoho Creator module Report_Export (#Report:All_Report_Exports)
async function uploadReportExportToZoho(blob, filename, mimeType, type) {
  var isPdf = (type === "pdf");
  var targetField = isPdf ? REPORT_EXPORT_PDF_FIELD : REPORT_EXPORT_EXCEL_FIELD;

  var fileObj;
  try {
    fileObj = new File([blob], filename, { type: mimeType, lastModified: Date.now() });
  } catch (e) {
    fileObj = blob;
    fileObj.name = filename;
  }

  var recordId = null;
  try {
    var addConfig = {
      form_name: REPORT_EXPORT_FORM,
      payload: {
        data: {}
      }
    };
    if (APP_LINK_NAME) addConfig.app_name = APP_LINK_NAME;

    var addResp = null;
    if (window.ZOHO && window.ZOHO.CREATOR && window.ZOHO.CREATOR.DATA && typeof window.ZOHO.CREATOR.DATA.addRecords === "function") {
      addResp = await window.ZOHO.CREATOR.DATA.addRecords(addConfig);
    } else if (window.ZOHO && window.ZOHO.CREATOR && window.ZOHO.CREATOR.API && typeof window.ZOHO.CREATOR.API.addRecord === "function") {
      addResp = await window.ZOHO.CREATOR.API.addRecord({
        formName: REPORT_EXPORT_FORM,
        data: { data: {} }
      });
    }

    recordId = extractRecordId(addResp);
    console.log("Report_Export record created with ID:", recordId);
  } catch (addErr) {
    console.warn("Failed to create record in " + REPORT_EXPORT_FORM + ":", addErr);
  }

  var serverDownloadUrl = "";
  if (recordId) {
    try {
      var uploadConfig = {
        report_name: REPORT_EXPORT_VIEW,
        id: recordId,
        field_name: targetField,
        file: fileObj
      };
      if (APP_LINK_NAME) uploadConfig.app_name = APP_LINK_NAME;

      if (window.ZOHO && window.ZOHO.CREATOR && window.ZOHO.CREATOR.FILE && typeof window.ZOHO.CREATOR.FILE.uploadFile === "function") {
        await window.ZOHO.CREATOR.FILE.uploadFile(uploadConfig);
      } else if (window.ZOHO && window.ZOHO.CREATOR && window.ZOHO.CREATOR.API && typeof window.ZOHO.CREATOR.API.uploadFile === "function") {
        await window.ZOHO.CREATOR.API.uploadFile(uploadConfig);
      }
      console.log("File uploaded successfully to " + REPORT_EXPORT_VIEW + " on field " + targetField);

      // Try fetching record to get direct download URL
      try {
        var recRes = await window.ZOHO.CREATOR.DATA.getRecordById({
          report_name: REPORT_EXPORT_VIEW,
          id: recordId
        });
        if (recRes && recRes.data && recRes.data[targetField]) {
          var relPath = recRes.data[targetField];
          if (/^https?:\/\//i.test(relPath)) {
            serverDownloadUrl = relPath;
          } else {
            if (!relPath.startsWith("/")) relPath = "/" + relPath;
            serverDownloadUrl = getPortalBaseUrl() + relPath;
          }
        }
      } catch (getRecErr) {
        console.warn("Could not retrieve file field from getRecordById:", getRecErr);
      }

      // Standard fallback Zoho Creator server download URL
      if (!serverDownloadUrl) {
        var baseUrl = getPortalBaseUrl();
        serverDownloadUrl = baseUrl + "/file/medielves/claims-management/" + REPORT_EXPORT_VIEW + "/" + recordId + "/" + targetField + "/download";
      }
    } catch (uploadErr) {
      console.warn("Failed to upload file to " + REPORT_EXPORT_VIEW + ":", uploadErr);
    }
  }

  return {
    recordId: recordId,
    targetField: targetField,
    downloadUrl: serverDownloadUrl
  };
}

async function downloadFileToDevice(blob, filename, mimeType, type) {
  var isApple = isIOS();
  var isPdf = (type === "pdf");
  var fileObj;
  try {
    fileObj = new File([blob], filename, { type: mimeType, lastModified: Date.now() });
  } catch (e) {
    fileObj = blob;
    fileObj.name = filename;
  }

  showToast("Downloading " + filename + " (" + formatBytes(blob.size) + ")…");

  // Step 1: On iOS (iPhone / iPad), use native Web Share API with File
  // This opens the native iOS system dialog with "Save to Files" (iCloud Drive / On My iPhone).
  if (isApple && navigator.share && navigator.canShare && navigator.canShare({ files: [fileObj] })) {
    try {
      await navigator.share({
        files: [fileObj],
        title: filename
      });
      showToast("File saved successfully!");
      return;
    } catch (shareErr) {
      if (shareErr.name === "AbortError") {
        return; // User cancelled
      }
      console.warn("navigator.share unavailable or blocked in iframe:", shareErr);
    }
  }

  // Step 2: Direct Blob download via anchor tag (Standard for Android & Desktop browsers)
  var blobUrl = URL.createObjectURL(blob);
  var a = document.createElement("a");
  a.style.display = "none";
  a.href = blobUrl;
  a.download = filename;
  a.rel = "noopener noreferrer";
  document.body.appendChild(a);
  a.click();

  // For iOS WebKit iframe fallback if anchor click is swallowed:
  if (isApple && isPdf) {
    setTimeout(function() {
      try {
        var newWin = window.open(blobUrl, "_blank");
        if (!newWin) {
          window.location.href = blobUrl;
        }
      } catch (e) {}
    }, 250);
  }

  setTimeout(function() {
    try {
      document.body.removeChild(a);
      URL.revokeObjectURL(blobUrl);
    } catch (e) {}
  }, 60000);
}

function showToast(message, duration) {
  duration = duration || 3000;
  var toast = document.getElementById("rp-toast");
  if (!toast) return;
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(toast._timeout);
  toast._timeout = setTimeout(function() {
    toast.classList.remove("show");
  }, duration);
}

function closeMobileExportModal() {
  var modal = document.getElementById("rp-export-modal");
  if (modal) {
    modal.classList.remove("open");
    modal.setAttribute("aria-hidden", "true");
  }
}

// Modal event listeners
var modalCloseBtn = document.getElementById("rp-modal-close-btn");
if (modalCloseBtn) modalCloseBtn.addEventListener("click", closeMobileExportModal);
var modalDoneBtn = document.getElementById("rp-modal-done-btn");
if (modalDoneBtn) modalDoneBtn.addEventListener("click", closeMobileExportModal);
var modalOverlay = document.getElementById("rp-export-modal");
if (modalOverlay) {
  modalOverlay.addEventListener("click", function(e) {
    if (e.target === modalOverlay) closeMobileExportModal();
  });
}

async function handleFileExport(blob, filename, mimeType, type) {
  var isMobile = isMobileDevice();
  var isPdf = (type === "pdf");

  // Save metadata to localStorage for persistence
  try {
    var key = isPdf ? LOCAL_STORAGE_PDF_KEY : LOCAL_STORAGE_EXCEL_KEY;
    localStorage.setItem(key + "_meta", JSON.stringify({
      filename: filename,
      mimeType: mimeType,
      type: type,
      size: blob.size,
      timestamp: new Date().toISOString()
    }));
  } catch (e) {}

  // Open modal immediately to show status and file details
  var modal = document.getElementById("rp-export-modal");
  var iconEl = document.getElementById("rp-modal-file-icon");
  var nameEl = document.getElementById("rp-modal-file-name");
  var sizeEl = document.getElementById("rp-modal-file-size");
  var statusBadge = document.getElementById("rp-modal-status-badge");
  var storageInfo = document.getElementById("rp-modal-storage-info");
  var titleEl = document.getElementById("rp-modal-title");
  var subtitleEl = document.getElementById("rp-modal-subtitle");
  var dlBtn = document.getElementById("rp-modal-download-btn");
  var dlTitle = document.getElementById("rp-download-btn-title");
  var dlSubtitle = document.getElementById("rp-download-btn-subtitle");

  if (iconEl) {
    iconEl.className = "export-option-icon " + (isPdf ? "pdf-icon" : "excel-icon");
    iconEl.textContent = isPdf ? "PDF" : "XLS";
  }
  if (nameEl) nameEl.textContent = filename;
  if (sizeEl) sizeEl.textContent = formatBytes(blob.size);

  if (titleEl) titleEl.textContent = "Saving Report…";
  if (subtitleEl) subtitleEl.textContent = "Saving to Zoho Creator Report_Export module";
  if (statusBadge) {
    statusBadge.innerHTML = "⏳ Saving to Module…";
    statusBadge.className = "me-badge me-badge-size";
  }
  if (storageInfo) {
    storageInfo.innerHTML = "Module: Report_Export &bull; Report: All_Report_Exports";
  }

  // Set download button to loading state initially
  if (dlBtn) {
    dlBtn.style.opacity = "0.7";
    dlBtn.disabled = true;
    if (dlTitle) dlTitle.textContent = "⏳ Saving to Module Report…";
    if (dlSubtitle) dlSubtitle.textContent = "Please wait while file is stored in Zoho Creator…";
  }

  if (modal) {
    modal.classList.add("open");
    modal.setAttribute("aria-hidden", "false");
  }

  showToast("Saving report to Zoho module (" + formatBytes(blob.size) + ")…");

  // Execute background save into Zoho Creator module Report_Export
  var zohoResult = await uploadReportExportToZoho(blob, filename, mimeType, type);

  // Successfully saved to Zoho Creator module!
  if (titleEl) titleEl.textContent = "Report Ready!";
  if (subtitleEl) subtitleEl.textContent = "Saved to Zoho module report successfully";
  if (statusBadge) {
    statusBadge.innerHTML = "&#10003; Saved in Module Report";
    statusBadge.className = "me-badge me-badge-success";
  }
  if (storageInfo) {
    var recText = (zohoResult && zohoResult.recordId) ? ("Record #" + zohoResult.recordId) : "Saved";
    storageInfo.innerHTML = "Report: All_Report_Exports &bull; " + recText + " &bull; Field: " + (zohoResult && zohoResult.targetField || (isPdf ? "Export_PDF" : "Export_Excel"));
  }

  if (dlBtn) {
    dlBtn.style.opacity = "1";
    dlBtn.disabled = false;
    if (dlTitle) dlTitle.textContent = "⬇ Download " + (isPdf ? "PDF" : "Excel");
    if (dlSubtitle) dlSubtitle.textContent = "Direct download (" + formatBytes(blob.size) + ") to device storage";

    dlBtn.onclick = async function(e) {
      e.preventDefault();
      await downloadFileToDevice(blob, filename, mimeType, type);
    };
  }

  showToast("✓ Report saved to module! Tap Download to save to device.");

  // On desktop browsers, trigger immediate download
  if (!isMobile) {
    downloadFileToDevice(blob, filename, mimeType, type);
  }
}

/* =================================================================
   LOADING STATE & STRICTLY SEQUENTIAL API ORCHESTRATION
   ================================================================= */

function setLoadingState(isLoading, message) {
  if (isLoading) {
    if (els.tbody) {
      els.tbody.innerHTML = '<tr><td colspan="12"><div class="rp-loading"><span class="rp-spinner"></span>' +
        escapeHtml(message || "Loading records…") + '</div></td></tr>';
    }
    if (els.count) {
      els.count.style.display = "block";
      els.count.textContent = message || "Loading records…";
    }
    if (els.filteredCount) {
      els.filteredCount.style.display = "none";
    }
  } else {
    if (els.count) {
      els.count.style.display = "none";
    }
    if (els.filteredCount) {
      els.filteredCount.style.display = "block";
    }
  }
}

// Step 0: Zoho Creator SDK Handshake
async function initZohoCreator() {
  if (typeof window.ZOHO !== "undefined" && window.ZOHO.CREATOR && typeof window.ZOHO.CREATOR.init === "function") {
    try {
      await window.ZOHO.CREATOR.init();
    } catch (err) {
      console.warn("ZOHO.CREATOR.init warning:", err);
    }
  }
}

// Step 1: API 1 — User Scope Resolution
async function resolveLoginUser() {
  loginUserEmail = "";
  try {
    if (window.ZOHO && window.ZOHO.CREATOR && window.ZOHO.CREATOR.UTIL && typeof window.ZOHO.CREATOR.UTIL.getInitParams === "function") {
      var params = await window.ZOHO.CREATOR.UTIL.getInitParams();
      loginUserEmail = (params && (params.loginUser || params.loginuser)) || "";
    }
  } catch (err) {
    console.warn("Could not retrieve init params via SDK:", err);
  }

  var isAdmin = USER_SCOPE.adminEmails.some(function(e) {
    return e.toLowerCase() === (loginUserEmail || "").toLowerCase();
  });

  if (!USER_SCOPE.enabled || isAdmin) {
    activePaymentCriteria = "";
    activeClaimCriteria = "";
    return;
  }

  if (loginUserEmail) {
    var safeEmail = loginUserEmail.replace(/"/g, '\\"');
    activePaymentCriteria = USER_SCOPE.paymentCriteria.replace(/\{\{email\}\}/g, safeEmail);
    activeClaimCriteria   = USER_SCOPE.claimCriteria.replace(/\{\{email\}\}/g, safeEmail);
  } else {
    console.warn("No loginUser identified in params; defaulting to open criteria to avoid breaking report on mobile.");
    activePaymentCriteria = "";
    activeClaimCriteria = "";
  }
}

// Rate-limited Zoho getRecords with Code 3100 ("No records found") resolution
async function zohoGetRecords(config, retries) {
  retries = retries !== undefined ? retries : 3;
  var delay = 600;
  for (var attempt = 0; attempt <= retries; attempt++) {
    try {
      if (!window.ZOHO || !window.ZOHO.CREATOR || !window.ZOHO.CREATOR.DATA || typeof window.ZOHO.CREATOR.DATA.getRecords !== "function") {
        throw new Error("Zoho Creator Data SDK not available");
      }
      var resp = await window.ZOHO.CREATOR.DATA.getRecords(config);
      return resp;
    } catch (err) {
      var errStr = JSON.stringify(err || "") + (err && err.message || "") + (err && err.responseText || "");
      if (errStr.includes("3100") || /no records|no data/i.test(errStr)) {
        // Zoho rejected because 0 records matched criteria — this is an empty set, not a fatal failure
        return { data: [] };
      }
      var isRateLimit = errStr.includes("429") || /rate limit|too many requests/i.test(errStr);
      if (isRateLimit && attempt < retries) {
        console.warn("Zoho rate-limited. Retrying in " + delay + "ms... (attempt " + (attempt + 1) + ")");
        await new Promise(function(r) { setTimeout(r, delay); });
        delay *= 2;
        continue;
      }
      throw err;
    }
  }
}

// Strictly sequential paginated report fetcher (no recursion, no parallel calls)
async function fetchReportRecordsSequentially(reportName, criteria, progressCallback) {
  var collected = [];
  var cursor = null;
  var pageIndex = 1;
  var hasMore = true;

  while (hasMore) {
    var config = {
      report_name: reportName,
      field_config: "all",
      max_records: 1000
    };
    if (APP_LINK_NAME) config.app_name = APP_LINK_NAME;
    if (criteria)      config.criteria = criteria;
    if (cursor)        config.record_cursor = cursor;

    try {
      var response = await zohoGetRecords(config, 3);
      var pageData = (response && Array.isArray(response.data)) ? response.data : [];

      for (var i = 0; i < pageData.length; i++) {
        collected.push(pageData[i]);
      }

      if (typeof progressCallback === "function") {
        progressCallback(collected.length, reportName, pageIndex);
      }

      var nextCursor = response && (response.record_cursor || (response.__meta && response.__meta.record_cursor));
      if (nextCursor && pageData.length > 0) {
        cursor = nextCursor;
        pageIndex++;
        // Short breathing room for mobile WebKit / iOS event loop
        await new Promise(function(r) { setTimeout(r, 60); });
      } else {
        hasMore = false;
        cursor = null;
      }
    } catch (pageErr) {
      console.error("Error fetching page for " + reportName + ":", pageErr);
      hasMore = false;
    }
  }

  return collected;
}

// Master Sequential Loader: API 1 -> wait/process -> API 2 -> wait/process -> API 3 -> wait/process -> render
async function loadRecords() {
  rawRecords = [];
  rawClaimRecords = [];
  selectedRows = {};

  setLoadingState(true, "Initializing widget…");

  try {
    // API 0: SDK handshake
    await initZohoCreator();

    // API 1: Resolve user identity & criteria
    setLoadingState(true, "Identifying user scope…");
    await resolveLoginUser();

    // API 2: Fetch Payment Report records sequentially
    setLoadingState(true, "Loading payment records…");
    rawRecords = await fetchReportRecordsSequentially(REPORT_LINK_NAME, activePaymentCriteria, function(count) {
      setLoadingState(true, "Loaded " + count + " payment records…");
    });

    // Pause between major APIs to let mobile browser process GC & network
    await new Promise(function(r) { setTimeout(r, 80); });

    // API 3: Fetch Claim Records sequentially (starts ONLY after API 2 has completed)
    setLoadingState(true, "Loading claim service dates…");
    try {
      rawClaimRecords = await fetchReportRecordsSequentially(CLAIMS_REPORT_LINK_NAME, activeClaimCriteria, function(count) {
        setLoadingState(true, "Loaded " + count + " claim records…");
      });
    } catch (claimErr) {
      console.warn("Could not load claims report; proceeding with payment records:", claimErr);
      rawClaimRecords = [];
    }

    // Process all loaded data sequentially
    setLoadingState(true, "Processing payment data…");
    allRecords = flattenRecords(rawRecords);
    if (rawClaimRecords && rawClaimRecords.length) {
      attachClaimServiceDates(allRecords, rawClaimRecords);
    }
    viewRecords = allRecords.slice();

    // Populate filter controls
    populateFilterOptions();
    var doctorNames = optionLists.doctor;
    if (els.doctor) {
      els.doctor.value = doctorNames.length ? doctorNames.join(", ") : "";
      els.doctor.placeholder = doctorNames.length ? "" : "No doctor found";
    }
    refreshClearButtons();

    // Render table & summary
    renderTable();
    setLoadingState(false);

    if (els.count) {
      els.count.textContent = allRecords.length + " payment line items loaded";
    }
  } catch (err) {
    console.error("Payment or claims report fetch failed:", err);
    setLoadingState(false);
    var msg = (err && err.message) ? err.message : "Check report names, network connection, or user criteria.";
    if (els.tbody) {
      els.tbody.innerHTML = '<tr><td colspan="12"><div class="rp-empty">Could not load payments. ' + escapeHtml(msg) + '</div></td></tr>';
    }
    if (els.count) {
      els.count.textContent = "Load failed";
    }
  }
}

// Kick off strictly sequential loading
loadRecords();
})();